25	/**
26	 * Enforces, on create, the maximum number of owners that may be registered on a single day.
27	 * <p>
28	 * The day is at capacity once {@link #MAX_OWNERS_PER_DAY} owners already carry the server's
29	 * current date as their registration date, at which point no further owner may be created that
30	 * day. The count reflects the owners stored before this create, so it must be checked before the
31	 * owner is saved.
32	 */
33	@Component
34	public class DailyRegistrationLimiter {
35	
36	    /** Maximum number of owners that may be registered on a single day. */
37	    static final int MAX_OWNERS_PER_DAY = 100;
38	
39	    private final ClinicService clinicService;
40	
41	    private final Clock clock;
42	
43	    public DailyRegistrationLimiter(ClinicService clinicService, Clock clock) {
44	        this.clinicService = clinicService;
45	        this.clock = clock;
46	    }
47	
48	    /**
49	     * Returns whether the server's current date has already reached its owner-registration
50	     * capacity, meaning no further owner may be created today. Call this before the owner is saved
51	     * so it does not count itself.
52	     *
53	     * @return {@code true} if {@link #MAX_OWNERS_PER_DAY} or more owners are already registered today
54	     */
55	    public boolean isDailyLimitReached() {
56	        return clinicService.countOwnersByRegistrationDate(LocalDate.now(clock)) >= MAX_OWNERS_PER_DAY;
57	    }
58	}
