26	 * The code is formatted {@code <CITY3>-<LAST3>-<NNNN>} where {@code CITY3} is the
27	 * upper-cased first three letters of the owner's city, {@code LAST3} the upper-cased
28	 * first three letters of the owner's last name, and {@code NNNN} is a per-city 4-digit
29	 * zero-padded sequence equal to one more than the number of owners already stored in
30	 * that city (e.g. {@code "SYD-SMI-0007"}).
31	 */
32	@Component
33	public class CustomerCodeAssigner {
34	
35	    private final ClinicService clinicService;
36	
37	    public CustomerCodeAssigner(ClinicService clinicService) {
38	        this.clinicService = clinicService;
39	    }
40	
41	    /**
42	     * Assigns {@code owner}'s customer code based on its city, last name and the current
43	     * per-city owner count. Call this before the owner is saved so the sequence reflects
44	     * the number of owners already stored in that city.
45	     *
46	     * @param owner the owner being created
47	     */
48	    public void assign(Owner owner) {
49	        String cityPrefix = prefix(owner.getCity());
50	        String lastNamePrefix = prefix(owner.getLastName());
51	        long sequence = clinicService.countOwnersByCity(owner.getCity()) + 1;
52	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence));
53	    }
54	
55	    /**
56	     * The upper-cased first three letters of {@code value} (fewer if it is shorter).
57	     */
58	    private String prefix(String value) {
59	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
60	    }
