17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.controller.CityCapacityChecker;
33	import org.springframework.samples.petclinic.rest.controller.CustomerCodeAssigner;
34	import org.springframework.samples.petclinic.rest.controller.DailyRegistrationLimiter;
35	import org.springframework.samples.petclinic.rest.controller.HouseholdAssigner;
36	import org.springframework.samples.petclinic.rest.controller.HouseholdDuplicateChecker;
37	import org.springframework.samples.petclinic.rest.controller.NamesakeCounter;
38	import org.springframework.samples.petclinic.rest.controller.OwnerFieldsValidator;
39	import org.springframework.samples.petclinic.rest.controller.RegistrationDateDefaulter;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.WebDataBinder;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.InitBinder;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final OwnerFieldsValidator ownerFieldsValidator;
75	
76	    private final RegistrationDateDefaulter registrationDateDefaulter;
77	
78	    private final CustomerCodeAssigner customerCodeAssigner;
79	
80	    private final HouseholdDuplicateChecker householdDuplicateChecker;
81	
82	    private final HouseholdAssigner householdAssigner;
83	
84	    private final NamesakeCounter namesakeCounter;
85	
86	    private final CityCapacityChecker cityCapacityChecker;
87	
88	    private final DailyRegistrationLimiter dailyRegistrationLimiter;
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper,
94	                                 OwnerFieldsValidator ownerFieldsValidator,
95	                                 RegistrationDateDefaulter registrationDateDefaulter,
96	                                 CustomerCodeAssigner customerCodeAssigner,
97	                                 HouseholdDuplicateChecker householdDuplicateChecker,
98	                                 HouseholdAssigner householdAssigner,
99	                                 NamesakeCounter namesakeCounter,
100	                                 CityCapacityChecker cityCapacityChecker,
101	                                 DailyRegistrationLimiter dailyRegistrationLimiter) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	        this.ownerFieldsValidator = ownerFieldsValidator;
107	        this.registrationDateDefaulter = registrationDateDefaulter;
108	        this.customerCodeAssigner = customerCodeAssigner;
109	        this.householdDuplicateChecker = householdDuplicateChecker;
110	        this.householdAssigner = householdAssigner;
111	        this.namesakeCounter = namesakeCounter;
112	        this.cityCapacityChecker = cityCapacityChecker;
113	        this.dailyRegistrationLimiter = dailyRegistrationLimiter;
114	    }
115	
116	    @InitBinder("ownerFieldsDto")
117	    void initOwnerFieldsBinder(WebDataBinder binder) {
118	        binder.addValidators(ownerFieldsValidator);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
124	        Collection<Owner> owners;
125	        if (lastName != null) {
126	            owners = this.clinicService.findOwnerByLastName(lastName);
127	        } else {
128	            owners = this.clinicService.findAllOwners();
129	        }
130	        if (owners.isEmpty()) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        if (this.clinicService.ownerExistsWithTelephone(owner.getTelephone())) {
152	            return new ResponseEntity<>(HttpStatus.CONFLICT);
153	        }
154	        if (this.cityCapacityChecker.isCityAtCapacity(owner)) {
155	            return new ResponseEntity<>(HttpStatus.CONFLICT);
156	        }
157	        if (this.dailyRegistrationLimiter.isDailyLimitReached()) {
158	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
159	        }
160	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
161	        boolean duplicate = this.householdDuplicateChecker.isDuplicate(owner);
162	        if (duplicate && !sharesHousehold) {
163	            return new ResponseEntity<>(HttpStatus.CONFLICT);
164	        }
165	        if (duplicate) {
166	            this.householdAssigner.assign(owner);
167	        }
168	        this.registrationDateDefaulter.applyDefault(owner);
169	        this.customerCodeAssigner.assign(owner);
170	        this.namesakeCounter.assign(owner);
171	        this.clinicService.saveOwner(owner);
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
181	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
182	        if (currentOwner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        currentOwner.setAddress(ownerFieldsDto.getAddress());
186	        currentOwner.setCity(ownerFieldsDto.getCity());
187	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
188	        currentOwner.setLastName(ownerFieldsDto.getLastName());
189	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
190	        currentOwner.setEmail(ownerFieldsDto.getEmail());
191	        this.clinicService.saveOwner(currentOwner);
192	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Transactional
197	    @Override
198	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
199	        Owner owner = this.clinicService.findOwnerById(ownerId);
200	        if (owner == null) {
201	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	        }
203	        this.clinicService.deleteOwner(owner);
204	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
210	        Owner owner = this.clinicService.findOwnerById(ownerId);
211	        if (owner == null) {
212	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	        }
214	        HttpHeaders headers = new HttpHeaders();
215	        Pet pet = petMapper.toPet(petFieldsDto);
216	        owner.setId(ownerId);
217	        pet.setOwner(owner);
218	        pet.getType().setName(null);
219	        this.clinicService.savePet(pet);
220	        PetDto petDto = petMapper.toPetDto(pet);
221	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
222	            .buildAndExpand(pet.getId()).toUri());
223	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
229	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
230	        if (currentOwner != null) {
231	            Pet currentPet = this.clinicService.findPetById(petId);
232	            if (currentPet != null) {
233	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
234	                currentPet.setName(petFieldsDto.getName());
235	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
236	                this.clinicService.savePet(currentPet);
237	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
238	            }
239	        }
240	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	    }
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
246	        HttpHeaders headers = new HttpHeaders();
247	        Visit visit = visitMapper.toVisit(visitFieldsDto);
248	        Pet pet = new Pet();
249	        pet.setId(petId);
250	        visit.setPet(pet);
251	        this.clinicService.saveVisit(visit);
252	        VisitDto visitDto = visitMapper.toVisitDto(visit);
253	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
254	            .buildAndExpand(visit.getId()).toUri());
255	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
256	    }
257	
258	
259	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
260	    @Override
261	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
262	        Owner owner = this.clinicService.findOwnerById(ownerId);
263	        if (owner != null) {
264	            Pet pet = owner.getPet(petId);
265	            if (pet != null) {
266	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
267	            }
268	        }
269	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
270	    }
271	}
